# -*- coding: utf-8 -*-
P = [
"@H1|۵۷. اگر توسعه یک «اتاق بحران» داشت",
"@P|این بخش یک «تمرین طراحی» است: اگر هیئت سرپرستی در بهمن ۱۴۰۰، هم‌زمان با «مصوبهٔ کمیتهٔ تخصصی اصلاح نظام بانکی»، یک «اتاق بحران» با پنج نقش تشکیل می‌داد، چه چیزی «تغییر» می‌کرد؟ و پاسخ، نه «معجزه» است و نه «حدس»؛ بلکه «فهرست کارهایی» است که در همان اسناد موجود، «نبودشان» قابل اثبات است. و لذا این بخش، «سناریوی فرضی» است و با همین برچسب ثبت می‌شود.",
"@P|**نقش اول: مالک پیام.** یک نفر که «همهٔ متن‌ها» — پیامک، نامه، بنر شعبه و پاسخ تلفنی — را «تأیید» می‌کند و «تنها سخنگو» است. در توسعه، این نقش «خالی» بود: پیامک از «هیئت سرپرستی» آمد، نامه از «هیئت سرپرستی» و «بنر» از «شعبه» — سه «منبع» با سه «لحن». و لذا «مخاطب» سه «روایت» شنید و «یکی» را باور کرد: «روایتی که او را بیشتر نگران می‌کرد».",
"@P|**نقش دوم: مالک داده.** یک نفر که «عدد» را «تأیید» می‌کند: «چند سپرده‌گذار»، «چقدر مانده»، «چه سهمی پرداخت‌شدنی است». در توسعه، «مالک داده» وجود نداشت و لذا «نامهٔ ۱۴ اسفند» «گزینه» گفت و «مبلغ» نگفت. و «گزینه بدون مبلغ»، «انتخاب کور» است.",
"@P|**نقش سوم: مالک کانال.** یک نفر که «دسترسی» به «پیامک انبوه»، «سایت»، «بنر شعبه» و «خط تلفن» دارد و «زمان‌بندی» را «هماهنگ» می‌کند. در توسعه، «کانال‌ها» در «واحدهای» مختلف بود و «هماهنگی» نداشت. و «پیامک» بیست‌وپنج روز پس از «مصوبه» رفت؛ و «بنر» پنج روز پیش از «مهلت». این «فاصله‌ها»، «نتیجهٔ» نبود «مالک کانال» است، نه «نتیجهٔ» نبود «فناوری».",
"@P|**نقش چهارم: مالک پاسخ.** یک تیم «چهار نفره» با «شیفت» و «متن آماده» و «شمارهٔ پیگیری». در توسعه، «تماس تک‌تک» جای این نقش را گرفت: یعنی «۴۰ تا ۶۰ تماس در روز» به «عهدهٔ» کارکنان شعبه، بدون «متن» و بدون «ثبت». و «تماس بدون ثبت»، «آمار» نمی‌سازد؛ «خستگی» می‌سازد.",
"@P|**نقش پنجم: مالک ثبت.** یک نفر که «همهٔ پرسش‌ها» را «دسته‌بندی» و «هفته‌ای» گزارش می‌کند تا «الگو» دیده شود. در توسعه، «حافظهٔ بحران» صفر بود: امروز نمی‌دانیم «پرتکرارترین پرسش» چه بود. و «نبود حافظه»، «تکرار خطا» را «قطعی» می‌کند.",
"@P|**و یک نکتهٔ طراحی:** این پنج نقش، «سازمان» نمی‌خواهد؛ «قرار» می‌خواهد. یعنی پنج «مسئولیت» که در یک «صورت‌جلسه» ثبت شود و «نام» داشته باشد. و در توسعه، «صورت‌جلسه» ثبت کرد که «چه کسی» عضو هیئت تصفیه است، اما ثبت نکرد که «چه کسی» پاسخ می‌دهد. و همین «تفاوت»، «هستهٔ» مسئله است.",
"@H1|۵۸. پنج مرز اخلاقی این پرونده",
"@P|هر پژوهش ارتباطی «مرز» دارد و در پروندهٔ توسعه پنج مرز روشن است. این مرزها «محدودیت» نیستند؛ «شرط اعتبار» هستند و هر یک، «اثر» خود را بر «متن» گذاشته است.",
"@P|**مرز اول: بدون تماس.** هیچ تماسی با سپرده‌گذار، سهامدار، کارمند یا ناظر گرفته نشد. و لذا هیچ «نقل‌قول دست‌اول» در این گزارش نیست. و هر «نقل‌قول»، از «منبع منتشرشده» است. و همین، «قدرت» گزارش را کم می‌کند و «اعتبار» آن را زیاد.",
"@P|**مرز دوم: بدون پیش‌بینی قیمت.** این گزارش نمی‌گوید «سهم توسعه چقدر می‌ارزید» یا «دارایی‌ها چقدر می‌ارزد». و «ارزش‌گذاری مجدد» یک «تحلیل سرمایه‌گذاری» است که در «مرز» این مجموعه نیست. و لذا «ادعای ۵۰ هزار میلیارد تومان» تنها با «برچسب روایت» آمده است.",
"@P|**مرز سوم: بدون انتساب نیت.** هیچ‌جا گفته نشده «مدیران می‌خواستند پنهان کنند». و فقط «متن»، «زمان» و «غیاب» توصیف شده است. و «نیت»، «قابل اثبات» نیست؛ «رفتار»، «قابل ثبت» است. و لذا «تز» با عبارت «به نظر می‌رسد» همراه شده است.",
"@P|**مرز چهارم: تفکیک ادعا از برداشت.** هر «برداشت» با «می‌توان خواند» یا «برداشت این گزارش» مشخص شده و هر «ادعا» با «شناسهٔ منبع». و در جدول منابع، «لایهٔ اعتبار» ثبت شده است. و این «تفکیک»، «قابل استناد بودن» را می‌سازد.",
"@P|**مرز پنجم: حفظ حرمت افراد.** نام «مدیران» تنها در «نقش رسمی» و «منبع منتشرشده» آمده و هیچ «اتهام فردی» در گزارش نیست. و «مسئله»، «ساختار» است، نه «شخص». و همین «مرز»، «ریسک حقوقی» را هم کم می‌کند.",
"@P|**و یک هزینه:** این پنج مرز، گزارش را «محافظه‌کارتر» می‌کند و «جذابیت» آن را کم. اما «اعتبار» آن را زیاد می‌کند؛ و در پرونده‌ای که «احساس» قوی است، «اعتبار» تنها «سپر» است.",
"@H1|۵۹. پنج هشدار برای مخاطب امروز",
"@P|امروز (آبان ۱۴۰۵)، «مؤسسه اعتباری توسعه» «نماد» ندارد، «سایت» ندارد و «میز خدمت» ندارد. اما «نام» آن، در «جست‌وجو» و در «محاوره» زنده است. و همین «نام»، «مصرف» می‌شود. و لذا پنج «هشدار» لازم است؛ نه «ادعای وقوع»، بلکه «الگوی ریسک».",
"@P|**هشدار اول: هم‌نامی توسعه تعاون.** «بانک توسعه تعاون» یک بانک دولتی «فعال» است و هیچ ارتباطی با «مؤسسه اعتباری توسعه» ندارد. و در ۱۴۰۲، «تشابه اسمی» باعث «شایعهٔ انحلال» آن شد (S09). و لذا هر پیامی که «توسعه تعاون» را «منحل» معرفی کند، «خطا» است.",
"@P|**هشدار دوم: مؤسسهٔ اعتباری توسعه‌ای.** دستورالعمل «مؤسسات اعتباری توسعه‌ای» در ۱۴۰۵ تصویب شد و «حداقل سرمایهٔ ۴۰۰ هزار میلیارد ریال» دارد (S17). این یک «نهاد جدید» است و نه «احیای» مؤسسهٔ منحله. و «نام مشابه»، «تلهٔ» تازه‌ای ساخته است.",
"@P|**هشدار سوم: صندوق توسعهٔ ملی.** یک «نهاد مالی توسعه‌ای» فعال با «مطالبات ارزی». و در «جست‌وجو»، نتایج آن با «توسعه» مخلوط می‌شود. و لذا هر «خبر» باید با «نام کامل» بازخوانی شود.",
"@P|**هشدار چهارم: «تصفیه» پایان نیست.** تا زمانی که «گزارش تصفیه» منتشر نشود، هر «وعدهٔ پرداخت» بیرون از «سند رسمی»، «ادعا» است. و لذا «مبنای راستی‌آزمایی»، «هیئت تصفیه» و «بانک مرکزی» است، نه «شبکه‌های اجتماعی».",
"@P|**هشدار پنجم: «سند بی‌صاحب».** وقتی «سازمان» منحل می‌شود و «برند» می‌ماند، «نام» می‌تواند «اجاره» داده شود. و لذا هر «خدمت» با نام «توسعه»، «استعلام مجوز» می‌خواهد. و «استعلام»، تنها «راه» تشخیص است.",
"@P|**و یک نکتهٔ ارتباطی:** این پنج هشدار، «حقوقی» نیستند؛ «ارتباطی» هستند. یعنی هدف، «حفاظت از مخاطب» است، نه «طرح دعوا». و در پرونده‌ای که «نام» زنده و «سازمان» مرده است، «حفاظت از نام» یک «وظیفهٔ» ارتباطی است.",
"@H1|۶۰. آموزه‌ها برای ناظر: سه قاعده",
"@P|این بخش «توصیه به ناظر» نیست؛ «استخراج قاعده از داده» است. ناظر در پروندهٔ توسعه چهار «ابزار» داشت: «رد صلاحیت»، «منع فعالیت»، «هیئت سرپرستی» و «انحلال». و هر چهار «به‌کار رفت»؛ اما «زبان» و «ترتیب» آن، «اثر» را کم کرد.",
"@P|**قاعدهٔ اول: «رد صلاحیت» ابزار «انضباطی» است، نه «ارتباطی».** در ۱۳۹۲ هیئت مدیره «مادام‌العمر» رد صلاحیت شد (S02) و «هیچ توضیحی» برای «سپرده‌گذار» منتشر نشد. و لذا «مخاطب» فقط «حکم» را دید و «دلیل» را نه. و «حکم بدون دلیل»، «ترس» می‌سازد، نه «اطمینان». و «ترس»، «هجوم» می‌آورد.",
"@P|**قاعدهٔ دوم: «سرپرستی» باید با «سخنگو» همراه باشد.** در ۱۳۹۷ هیئت سرپرستی تعیین شد (S02) و «مخاطب» نفهمید «چه تغییری» رخ داده. و لذا «سرپرستی» در «افکار عمومی» به «نشانهٔ ورشکستگی» تبدیل شد، نه «نشانهٔ اصلاح». و «سخنگو» — یک نام و یک شماره — می‌توانست این «برداشت» را عوض کند.",
"@P|**قاعدهٔ سوم: «انحلال» باید «نقشهٔ پرداخت» داشته باشد.** در ۱۴۰۲ «تصفیهٔ یک‌ساله» تصویب شد (S02) و «نقشهٔ پرداخت» منتشر نشد. و لذا «مخاطب» سه سال «منتظر» ماند. و «انتظار بدون تاریخ»، «خشم» انباشته می‌کند؛ و «خشم انباشته» در «نظام بانکی»، «هزینهٔ اعتماد» است.",
"@P|**و یک قاعدهٔ چهارم، از دل سه قاعده:** «هر تصمیم نهادی» باید «یک سند ارتباطی» داشته باشد: «چه شد»، «چه می‌شود» و «کجا بپرسیم». و این «سند»، «سه جمله» است و «هزینهٔ» آن «نزدیک صفر». و در توسعه، «سه تصمیم» بزرگ (۱۳۹۲، ۱۳۹۷، ۱۴۰۲) و «صفر سند».",
"@H1|۶۱. آموزه‌ها برای هیئت تصفیه: پنج گام",
"@P|هیئت تصفیه، «وارث» یک «پروندهٔ ارتباطی» است، نه فقط «ترازنامه». و اگر «پنج گام» را اجرا کند، «هزینهٔ» اجتماعی «انحلال» کم می‌شود. و هر گام، در همین گزارش «شاهد» دارد.",
"@P|**گام اول: انتشار «شناسنامهٔ پرونده».** یک صفحه با «تاریخ انحلال»، «شمارهٔ مصوبه»، «اعضای هیئت»، «شمارهٔ تماس» و «نشانی». و در توسعه، «صورت‌جلسه» هست (S02) و «شناسنامه» نیست. و همین «صفحه»، «مرجع» همهٔ «جست‌وجوها» می‌شود.",
"@P|**گام دوم: انتشار «برگهٔ روش تصفیه».** یک سند سه‌ستونی: «دارایی‌ها» (فهرست و ارزش)، «بدهی‌ها» (سپرده، تعهدات) و «ترتیب پرداخت» (اولویت‌ها). و در توسعه، «ارزش‌گذاری» منتشر نشد. و همین، «بزرگ‌ترین شکاف» است.",
"@P|**گام سوم: گزارش شش‌ماهه.** چهار صفحه با «سه عدد»: «پرداخت‌شده»، «باقی‌مانده» و «زمان‌بندی». و «تعهد انتشار» در «تقویم». و در توسعه، «بازهٔ یک‌ساله» بدون «گزارش» ماند.",
"@P|**گام چهارم: کانال پاسخ.** یک «شماره»، یک «سامانه» و یک «مسئول». و «تعهد» ۴۸ ساعت. و در توسعه، «تماس تک‌تک» بود و «کانال» نبود.",
"@P|**گام پنجم: نامهٔ پایانی.** یک متن ۳۰۰ واژه‌ای برای «سه مخاطب» و یک «گزارش نهایی». و در توسعه، «نامه» نبود.",
"@P|**و یک نکتهٔ عملی:** این پنج گام، «منابع» نمی‌خواهد؛ «تصمیم» می‌خواهد. و در پرونده‌ای که «سه سال» گذشته، «شروع» از «امروز» هم «مفید» است؛ چون «حافظه» را «بازسازی» می‌کند.",
]
